//! The assistant reaches every property the model declares.
//!
//! The class closed here is "a property is added to the model and stays
//! invisible to the assistant". `WireLookParam`, `WireMaskParam`,
//! `WireStyleParam`, `WireTextParam`, and `WireShapeParam` restate the model's
//! variant lists, and `lower::clip_param` maps them across one arm at a time.
//! Nothing tied the two sides together, so a new property was reachable in the
//! editor and silently absent from the tool schema.
//!
//! These tests walk the model's own census — `LookParam::ALL` and friends,
//! generated by the macro that declares each enum — and require that every
//! variant (a) has a wire member under the same serde name, and (b) lowers back
//! to exactly that variant. A property added to the model therefore turns this
//! suite red until the wire enum and the lowering arm exist.
//!
//! What this does not catch: a wire member with no model counterpart. That is a
//! compile error in the lowering match instead, which is the stronger signal.

use aria_models::{
    Clip, Generator, LookParam, Mask, MaskKind, MaskParam, Rational, ShapeParam, StyleParam,
    TextParam,
};

use super::lower;
use crate::wire::{
    WireClipParam, WireLookParam, WireMaskParam, WireShapeParam, WireStyleParam, WireTextParam,
};

/// Any clip: `clip_param` reads the clip only to resolve an effect slot, and no
/// axis property is an effect property.
fn any_clip() -> Clip {
    Clip::generated(
        Generator::SolidColor {
            rgba: [0, 0, 0, 255],
        },
        aria_models::TimeRange::at_rate(0, 48, Rational::FPS_24),
    )
}

/// The serde name a variant serialises to, which is the name the wire member
/// must answer to. Going through serde rather than a hand-written string keeps
/// the two sides bound to one spelling.
fn wire_name<T: serde::Serialize>(variant: &T) -> String {
    serde_json::to_string(variant).expect("a unit enum variant serializes")
}

#[test]
fn every_look_param_has_a_wire_member_that_lowers_back_to_it() {
    let clip = any_clip();
    for model in LookParam::ALL {
        let name = wire_name(model);
        let wire: WireLookParam = serde_json::from_str(&name).unwrap_or_else(|_| {
            panic!("LookParam::{model:?} ({name}) has no WireLookParam member")
        });
        let lowered = lower::clip_param(&WireClipParam::Look { param: wire }, &clip, 1)
            .expect("an axis property never needs an effect slot");
        assert_eq!(
            lowered,
            aria_models::ClipParam::Look { param: *model },
            "{name} lowers to the wrong property"
        );
    }
}

/// A mask property lowers against the mask it names, so the clip carries two
/// and the second is addressed: a lowering that dropped the index would land on
/// the first.
#[test]
fn every_mask_param_has_a_wire_member_that_lowers_back_to_it() {
    let mut clip = any_clip();
    clip.masks = vec![Mask::new(MaskKind::Circle), Mask::new(MaskKind::Star)];
    for model in MaskParam::ALL {
        let name = wire_name(model);
        let wire: WireMaskParam = serde_json::from_str(&name).unwrap_or_else(|_| {
            panic!("MaskParam::{model:?} ({name}) has no WireMaskParam member")
        });
        let lowered = lower::clip_param(
            &WireClipParam::Mask {
                index: 1,
                param: wire,
            },
            &clip,
            1,
        )
        .expect("the clip has a mask at index 1");
        assert_eq!(
            lowered,
            aria_models::ClipParam::Mask {
                mask: 1,
                param: *model
            },
            "{name} lowers to the wrong property"
        );
    }
}

