/// The census is not empty and has not silently shrunk to one axis. A test that
/// iterates an empty list passes, which is the failure mode this guards.
#[test]
fn the_property_census_is_the_size_the_model_declares() {
    assert_eq!(LookParam::ALL.len(), 67);
    assert_eq!(MaskParam::ALL.len(), 7);
    assert_eq!(StyleParam::ALL.len(), 11);
    assert_eq!(TextParam::ALL.len(), 11);
    assert_eq!(ShapeParam::ALL.len(), 7);
}

/// Every grade slider the model declares is animatable by the assistant.
///
/// The look census above walks `LookParam`, which is the property axis. This
/// walks the *grade* — the slider table on `ColorAdjustments` — and requires a
/// `LookParam` route, a wire member, and a lowering for each. A grade field
/// added with a slider row but no property route is settable in the panel and
/// invisible to the assistant, which is the shape of the last two gaps here
/// (tint/hue, then the colour wheels).
#[test]
fn every_grade_slider_is_reachable_as_a_look_property() {
    let clip = any_clip();
    for slider in aria_models::ColorAdjustments::SLIDERS {
        let name = format!("\"adjust_{}\"", slider.name);
        let wire: WireLookParam = serde_json::from_str(&name)
            .unwrap_or_else(|_| panic!("grade slider {} has no wire member", slider.name));
        let lowered = lower::clip_param(&WireClipParam::Look { param: wire }, &clip, 1)
            .expect("an axis property never needs an effect slot");
        let aria_models::ClipParam::Look { param } = lowered else {
            panic!("{name} lowered to something other than a look property");
        };
        assert!(
            LookParam::ALL.contains(&param),
            "{name} lowered outside the look census"
        );
    }
}
